JOIN public.flocks f ON f.flock_no = v.fno
JOIN public.hatcheries h ON h.name = v.hname;

-- VERIFY 2: how many landed, and are the dates real rather than stacked?
SELECT COUNT(*)::text AS batches, COUNT(hatch_date)::text AS with_hatch_date,
       COUNT(DISTINCT setting_date)::text AS distinct_setting_dates,
       MIN(setting_date)::text AS earliest, MAX(setting_date)::text AS latest,
       COUNT(*) FILTER (WHERE hatch_date - setting_date = 21)::text AS gap_21_days
FROM public.hatch_batches;

-- VERIFY 3: every row linked to a flock and to the hatchery master -- a row
-- that failed either JOIN would simply be missing, so the count is the proof.
SELECT COUNT(*)::text AS total, COUNT(flock_id)::text AS with_flock,
       COUNT(hatchery_id)::text AS linked_to_master,
       COUNT(std_hatch_pct)::text AS with_std_pct,
       COUNT(std_chicks)::text AS with_std_chicks
FROM public.hatch_batches;

-- VERIFY 4: per hatchery, so the split matches the workbook
-- (Ruiya Top Floor 106, Ruiya Ground Floor 95, NilGanj 70,
--  Paridhi Hatchery(Dankuni) 62, Howrah 61).
SELECT COALESCE(string_agg(nm || ': ' || c, ' | ' ORDER BY c DESC), 'NONE') AS by_hatchery
FROM (SELECT h.name AS nm, COUNT(*) AS c FROM public.hatch_batches b
      JOIN public.hatcheries h ON h.id = b.hatchery_id GROUP BY h.name) x;

-- VERIFY 5: the totals the page will now show, and the shortfall against
-- standard across the whole set.
SELECT SUM(eggs_set)::text AS eggs_received,
       SUM(eggs_set - broken_transit)::text AS setting,
       SUM(hatched_chicks)::text AS hatched,
       SUM(std_chicks)::text AS std_expected,
       SUM(hatched_chicks - rejects)::text AS actual_std,
       (SUM(hatched_chicks - rejects) - SUM(std_chicks))::text AS actual_minus_standard
FROM public.hatch_batches;
